#!/usr/bin/env node
// Static checks for the Style UI catalog. Run with: node scripts/validate.js

const fs = require("node:fs");
const path = require("node:path");

const ROOT = path.resolve(__dirname, "..");
const PAGES = [
  "index.html",
  "ui-components/index.html",
  "background-generator/index.html",
  "design-md/index.html",
];
const HTML_PAGES = [...PAGES, "404.html"];
const VALID_STATUS = new Set(["Free", "Paid", "Semi-free"]);
const IMAGE_BUDGET_BYTES = 300 * 1024;
const REQUIRED_FILES = [
  "index.html",
  "404.html",
  "README.md",
  "LICENSE",
  "CONTRIBUTING.md",
  "CODE_OF_CONDUCT.md",
  "SECURITY.md",
  "PRIVACY.md",
  "ROADMAP.md",
  "robots.txt",
  "sitemap.xml",
  "site.webmanifest",
  "vercel.json",
];

const errors = [];
const warnings = [];
const fail = (message) => errors.push(message);
const warn = (message) => warnings.push(message);

function read(relativePath) {
  return fs.readFileSync(path.join(ROOT, relativePath), "utf8");
}

for (const file of REQUIRED_FILES) {
  if (!fs.existsSync(path.join(ROOT, file))) fail(`missing required file: ${file}`);
}

// Local asset references resolve. The pattern captures any scheme or leading
// slash so absolute URLs are skipped and root-relative paths use the repo root.
const assetPattern = /(?:https?:\/\/[^\s"'<>]+)?(?:\.\.\/|\/)?assets\/[A-Za-z0-9._/-]+\.(?:png|jpe?g|webp|svg|ico|css|js)/g;
const sourceFiles = [
  ...HTML_PAGES,
  "README.md",
  "site.webmanifest",
  ...fs.readdirSync(path.join(ROOT, "assets/css")).map((name) => `assets/css/${name}`),
  ...fs.readdirSync(path.join(ROOT, "assets/js")).map((name) => `assets/js/${name}`),
];

for (const file of sourceFiles) {
  const text = read(file);
  const seen = new Set();
  for (const match of text.match(assetPattern) || []) {
    if (seen.has(match)) continue;
    seen.add(match);
    if (/^https?:\/\//.test(match)) continue;
    const resolved = match.startsWith("/")
      ? path.join(ROOT, match.slice(1))
      : path.resolve(ROOT, path.dirname(file), match);
    if (!fs.existsSync(resolved)) {
      fail(`${file}: referenced asset does not exist -> ${match}`);
      continue;
    }
    if (/\.(png|jpe?g|webp)$/i.test(resolved)) {
      const size = fs.statSync(resolved).size;
      if (size > IMAGE_BUDGET_BYTES) {
        fail(`${file}: image over 300 KB (${Math.round(size / 1024)} KB) -> ${match}`);
      }
    }
  }
}

// Root-relative links in HTML must point at a real file.
const rootRefPattern = /(?:href|src)="(\/[^"#?]+\.(?:png|jpe?g|webp|svg|ico|css|js|xml|txt|webmanifest))"/g;
for (const page of HTML_PAGES) {
  for (const match of read(page).matchAll(rootRefPattern)) {
    if (!fs.existsSync(path.join(ROOT, match[1].slice(1)))) {
      fail(`${page}: root-relative link does not exist -> ${match[1]}`);
    }
  }
}

// Card data on each catalog page.
for (const page of PAGES) {
  const text = read(page);
  const cards = text.match(/<a\b[^>]*class="g4-card"[^>]*>/g) || [];
  const hasTabs = /class="t-tab"/.test(text);
  const counts = new Map();
  const urls = new Map();

  for (const tag of cards) {
    const status = (tag.match(/data-status="([^"]*)"/) || [])[1];
    const name = (tag.match(/data-name="([^"]*)"/) || [])[1];
    const href = (tag.match(/href="([^"]*)"/) || [])[1];

    if (hasTabs) {
      if (!status || !VALID_STATUS.has(status)) {
        fail(`${page}: card with invalid data-status "${status}" (${name || href || "unnamed"})`);
      } else {
        counts.set(status, (counts.get(status) || 0) + 1);
      }
      if (!name) fail(`${page}: card missing data-name (${href || "unnamed"})`);
    }

    if (href) {
      if (urls.has(href)) fail(`${page}: duplicate tool URL ${href}`);
      urls.set(href, true);
      if (href.startsWith("http://")) fail(`${page}: insecure link ${href}`);
    }
  }

  // Tab badges must match the cards actually on the page.
  const tabPattern = /<button[^>]*class="t-tab"[^>]*data-filter="([^"]+)"[^>]*>[\s\S]*?<span class="tab-badge">(\d+)<\/span>/g;
  let tabMatch;
  let badgeTotal = 0;
  while ((tabMatch = tabPattern.exec(text)) !== null) {
    const filter = tabMatch[1];
    const badge = Number(tabMatch[2]);
    if (filter === "all") {
      badgeTotal = badge;
    } else {
      const actual = counts.get(filter) || 0;
      if (badge !== actual) {
        fail(`${page}: "${filter}" tab badge says ${badge}, page has ${actual}`);
      }
    }
  }
  if (hasTabs && badgeTotal !== cards.length) {
    fail(`${page}: "All" tab badge says ${badgeTotal}, page has ${cards.length} cards`);
  }

  if (cards.length === 0) warn(`${page}: no tool cards found`);
}

// Accessibility basics on catalog images.
for (const page of HTML_PAGES) {
  const text = read(page);
  const imgs = text.match(/<img\b[^>]*>/g) || [];
  for (const img of imgs) {
    if (!/\balt="/.test(img)) fail(`${page}: <img> without alt -> ${img.slice(0, 90)}`);
  }
}

// Em dashes are banned in this project.
const EM_DASH = "—";
const COPY_FILES = [...HTML_PAGES, "README.md", "ROADMAP.md", "CONTRIBUTING.md", "SECURITY.md", "PRIVACY.md", "CODE_OF_CONDUCT.md"];
for (const file of COPY_FILES) {
  if (read(file).includes(EM_DASH)) fail(`${file}: contains an em dash`);
}

for (const message of warnings) console.warn(`warn  ${message}`);
for (const message of errors) console.error(`error ${message}`);

if (errors.length > 0) {
  console.error(`\n${errors.length} problem(s) found.`);
  process.exit(1);
}

console.log(`All checks passed. ${warnings.length} warning(s).`);

from pathlib import Path
import re
import sys

ROOT = Path(__file__).resolve().parent.parent
LIVE_TEXT_FILES = [
    ROOT / "index.html",
    ROOT / "ui-components" / "index.html",
    ROOT / "background-generator" / "index.html",
    ROOT / "design-md" / "index.html",
    ROOT / "README.md",
    ROOT / "site.webmanifest",
    *sorted((ROOT / "assets" / "css").glob("*.css")),
    *sorted((ROOT / "assets" / "js").glob("*.js")),
]
ASSET_PATTERN = re.compile(r"assets/[A-Za-z0-9._/-]+\.(?:png|jpg|jpeg|webp|svg|ico|css|js)")
KEEP = {
    "assets/vendor/README.md",
    "assets/vendor/lenis/LICENSE",
    # Root /favicon.ico fallback for browsers that request it directly.
    "assets/images/favicon.ico",
}


def referenced_assets() -> set[str]:
    found = set()
    for path in LIVE_TEXT_FILES:
        text = path.read_text(encoding="utf-8")
        for match in ASSET_PATTERN.finditer(text):
            found.add(match.group(0))
    return found


def main() -> None:
    dry_run = "--delete" not in sys.argv
    referenced = referenced_assets()
    delete_list = []

    for folder in ("previews", "logos", "images"):
        for path in sorted((ROOT / "assets" / folder).rglob("*")):
            if not path.is_file():
                continue
            relative = path.relative_to(ROOT).as_posix()
            if relative in referenced or relative in KEEP:
                continue
            delete_list.append(path)

    total = sum(path.stat().st_size for path in delete_list)
    print(f"{'Would delete' if dry_run else 'Deleting'} {len(delete_list)} files, {total / 1024 / 1024:.1f} MB")
    for path in delete_list:
        print(path.relative_to(ROOT).as_posix())

    if not dry_run:
        for path in delete_list:
            path.unlink()


if __name__ == "__main__":
    main()

from pathlib import Path
import re

from PIL import Image

ROOT = Path(__file__).resolve().parent.parent
LIVE_FILES = [
    ROOT / "index.html",
    ROOT / "ui-components" / "index.html",
    ROOT / "background-generator" / "index.html",
    ROOT / "design-md" / "index.html",
    ROOT / "assets" / "css" / "components.css",
]

ASSET_PATTERN = re.compile(
    r"(?:\.\./)?assets/(?:previews|logos|images)/[A-Za-z0-9._-]+\.(?:png|jpg|jpeg)"
)

# Social platforms prefer JPEG for link previews, so keep this out of the WebP pass.
SKIP = {"assets/images/og-image.jpg"}


def webp_path(path: Path) -> Path:
    return path.with_suffix(".webp")


def optimize_preview(path: Path) -> None:
    image = Image.open(path).convert("RGB")
    if image.width > 960:
        height = round(image.height * 960 / image.width)
        image = image.resize((960, height), Image.Resampling.LANCZOS)
    image.save(webp_path(path), "WEBP", quality=80, method=6)


def optimize_logo(path: Path) -> None:
    image = Image.open(path).convert("RGBA")
    if image.width > 128 or image.height > 128:
        image.thumbnail((128, 128), Image.Resampling.LANCZOS)
    image.save(webp_path(path), "WEBP", quality=85, method=6)


def optimize_hero(path: Path) -> None:
    image = Image.open(path).convert("RGB")
    image.save(webp_path(path), "WEBP", quality=82, method=6)


def main() -> None:
    texts = {path: path.read_text(encoding="utf-8") for path in LIVE_FILES}
    references = set()

    for text in texts.values():
        for match in ASSET_PATTERN.finditer(text):
            if match.group(0) in SKIP:
                continue
            references.add(match.group(0))

    converted = []
    for reference in sorted(references):
        relative = reference.replace("../", "")
        source = ROOT / relative
        if not source.exists():
            print("Missing:", reference)
            continue

        if "/previews/" in relative:
            optimize_preview(source)
        elif "/logos/" in relative:
            optimize_logo(source)
        elif "/images/" in relative and source.suffix.lower() in {".jpg", ".jpeg"}:
            optimize_hero(source)
        else:
            continue

        converted.append((reference, reference.rsplit(".", 1)[0] + ".webp"))

    for path, text in texts.items():
        updated = text
        for old, new in converted:
            updated = updated.replace(old, new)
        path.write_text(updated, encoding="utf-8")

    logo = ROOT / "assets" / "images" / "logo.png"
    if logo.exists():
        image = Image.open(logo).convert("RGB")
        image = image.resize((512, 512), Image.Resampling.LANCZOS)
        image.save(logo, optimize=True)

    print(f"Converted {len(converted)} referenced assets to WebP")
    for old, new in converted:
        print(f"  {old} -> {new}")


if __name__ == "__main__":
    main()

(function () {
  'use strict';

  function initTheme() {
    const themeToggles = document.querySelectorAll('#theme-toggle, .subpage-theme-toggle');
    if (themeToggles.length === 0) return;

    function updateThemeIcons(theme) {
      themeToggles.forEach((btn) => {
        const sun = btn.querySelector('.sun-icon');
        const moon = btn.querySelector('.moon-icon');
        if (theme === 'light') {
          if (sun) sun.classList.add('active');
          if (moon) moon.classList.remove('active');
        } else {
          if (moon) moon.classList.add('active');
          if (sun) sun.classList.remove('active');
        }
      });
    }

    const isMobileOrTablet = window.innerWidth <= 1024;
    const deviceKey = isMobileOrTablet ? 'style_ui_theme_mobile' : 'style_ui_theme_desktop';
    let activeTheme = document.documentElement.getAttribute('data-theme');

    try {
      const savedTheme = localStorage.getItem(deviceKey);
      if (savedTheme) {
        activeTheme = savedTheme;
      } else if (!activeTheme) {
        activeTheme = isMobileOrTablet ? 'light' : 'dark';
      }
    } catch (e) {
      if (!activeTheme) activeTheme = isMobileOrTablet ? 'light' : 'dark';
    }

    document.documentElement.setAttribute('data-theme', activeTheme);
    updateThemeIcons(activeTheme);

    themeToggles.forEach((btn) => {
      btn.addEventListener('click', function () {
        const currentTheme = document.documentElement.getAttribute('data-theme') || 'dark';
        const nextTheme = currentTheme === 'dark' ? 'light' : 'dark';

        document.documentElement.setAttribute('data-theme', nextTheme);
        try {
          localStorage.setItem(deviceKey, nextTheme);
        } catch (e) {}

        updateThemeIcons(nextTheme);
      });
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initTheme);
  } else {
    initTheme();
  }
})();
